export const Account = Schema.Struct({ accountId: ParticipantId, email: Email, name: Name, admin: Schema.Boolean });
export const Run = Schema.Struct({ runId: Id, sessionId: Id, askedBy: ParticipantId, asked: Text, status: RunStatus, … });
export const SessionView = Schema.Struct({ sessionId: Id, planId: Id, startedBy: ParticipantId, participants: …, runs: … });

